// ---- insertion logic (CRLF-safe, comma-guarded, abort if any id present) ----
const check = process.argv.includes('--check');
const doQa = process.argv.includes('--qa');
let applied = 0;
for (const file of Object.keys(T)) {
  const fp = path.join(ROOT, 'js', 'data', file + '.js');
  let src = fs.readFileSync(fp, 'utf8');
  const ids = T[file].map(c => c.match(/\{ id: '([^']+)'/)[1]);
  const present = ids.filter(id => src.includes("id: '" + id + "'"));
  if (present.length) { console.error('[ABORT] ' + file + ' already contains: ' + present.join(', ')); process.exit(1); }
  const anchor = src.lastIndexOf('\r\n];');
  if (anchor < 0) { console.error('[ABORT] no CRLF ]; tail in ' + file); process.exit(1); }
  const before = src.slice(0, anchor);
  const sep = /,\s*$/.test(before) ? '\r\n\r\n' : ',\r\n\r\n';
  const block = T[file].map(c => '  ' + c).join(',\r\n\r\n');
  const out = before + sep + block + src.slice(anchor);
  if (!check) {
    try { new Function(out); } catch (e) { console.error('[ABORT] ' + file + ' would not parse: ' + e.message); process.exit(1); }
    fs.writeFileSync(fp, out);
  }
  applied += ids.length;
  console.log('[ok] ' + file + ': +' + ids.length + ' tools');
}
if (doQa) {
  const tfp = path.join(ROOT, 'tests', 'unit', 'formula-qa-full.test.js');
  let tsrc = fs.readFileSync(tfp, 'utf8');
  const firstRow = "['finance', 'payout-ratio'";
  if (tsrc.includes(firstRow)) { console.log('[skip] QA rows already present'); }
  else {
    const start = tsrc.indexOf('const CASES = [');
    const close = tsrc.indexOf('\n];', start);
    if (start < 0 || close < 0) { console.error('[ABORT] CASES array not found'); process.exit(1); }
    tsrc = tsrc.slice(0, close) + '\n' + QA_ROWS.join('\n') + tsrc.slice(close);
    if (!check) fs.writeFileSync(tfp, tsrc);
    console.log('[ok] +' + QA_ROWS.length + ' QA rows');
  }
}
console.log((check ? '[DRY RUN] would insert ' : 'Inserted ') + applied + ' finance tools');
